<?php

function genv($env, $def) {
    $res = getenv($env);
    if ($res) return $res;
    return $def;
}

function genvBool($env, $def) {
    $res = getenv($env);
    if ($res === false || $res === '') return $def;
    return filter_var($res, FILTER_VALIDATE_BOOLEAN);
}

