# Login through netBS (OpenID Connect provider)
wfLoadExtension( 'PluggableAuth' );
wfLoadExtension( 'OpenIDConnect' );

# Members of this netBS role group (sent in the `groups` claim) are made
# sysop + bureaucrat on every login, and lose both when they leave it.
# Empty disables the sync and admins are managed by hand in the wiki.
$wikiAdminGroup = getenv("OIDC_ADMIN_GROUP");
if ($wikiAdminGroup === false) $wikiAdminGroup = "wiki-admins";

$wgPluggableAuth_Config = [
    genv("OIDC_BUTTON_LABEL", "Se connecter avec netBS") => [
        'plugin' => 'OpenIDConnect',
        'data' => [
            'providerURL'         => genv("OIDC_PROVIDER_URL", ""),
            'clientID'            => genv("OIDC_CLIENT_ID", ""),
            'clientsecret'        => genv("OIDC_CLIENT_SECRET", ""),
            'scope'               => explode(' ', genv("OIDC_SCOPE", "openid profile email groups")),
            'authMethods'         => [ genv("OIDC_AUTH_METHOD", "client_secret_post") ],
            'codeChallengeMethod' => 'S256',
        ],
        'groupsyncs' => $wikiAdminGroup === "" ? [] : [ [
            'type' => 'mapped',
            'map'  => [
                'sysop'      => [ 'groups' => $wikiAdminGroup ],
                'bureaucrat' => [ 'groups' => $wikiAdminGroup ],
            ],
        ] ],
    ],
];

# Skip the login page and send users straight to netBS
$wgPluggableAuth_EnableAutoLogin = genvBool("OIDC_AUTO_LOGIN", false);
# Keep the local username/password form next to the netBS button
$wgPluggableAuth_EnableLocalLogin = genvBool("OIDC_LOCAL_LOGIN", false);
# Link existing wiki accounts (created by the former netBS DB login) to
# their netBS identity on first login, matching on username
$wgOpenIDConnect_MigrateUsersByUserName = genvBool("OIDC_MIGRATE_USERS_BY_USERNAME", true);

